/** Native checks for the new rate menus on real slot-0 records. Shipping JAR never contains this driver. */
@SpireInitializer public class StatsOptionsProbe implements PostUpdateSubscriber,PostRenderSubscriber {
    int stage;long next,started=System.currentTimeMillis();String shot,neowObserved;boolean captured;MainMenuScreen.CurScreen prior;JsonObject report=new JsonObject();Path exportBefore,exportNow;
    public static void initialize(){BaseMod.subscribe(new StatsOptionsProbe());}
    @SpirePatch(clz=DistributorFactory.class,method="getEnabledDistributor") public static class Offline {@SpirePrefixPatch public static SpireReturn<PublisherIntegration> before(String distributor){return SpireReturn.Return(new GogIntegration());}}
    @SpirePatch(clz=CardCrawlGame.class,method="create") public static class NoSteam {@SpireInstrumentPatch public static ExprEditor edit(){return new ExprEditor(){public void edit(NewExpr e)throws CannotCompileException{if(e.getClassName().equals("com.codedisaster.steamworks.SteamUtils")||e.getClassName().equals("com.megacrit.cardcrawl.helpers.steamInput.SteamInputHelper"))e.replace("{ $_ = null; }");}};}}
    @SpirePatch(clz=Settings.class,method="initializeGamePref") public static class Chinese {@SpirePostfixPatch public static void lang(){Settings.setLanguage(Settings.GameLanguage.valueOf(System.getProperty("spireledger.uiLanguage","ZHS")),true);}}
    static Object fade()throws Exception{java.lang.reflect.Field f=CardCrawlGame.class.getDeclaredField("screenColor");f.setAccessible(true);return f.get(null);}
    static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
    static void clicked(Hitbox h){h.clicked=true;InputHelper.mX=(int)h.cX;InputHelper.mY=(int)h.cY;}
    void dropdown(DropdownMenu d,int row)throws Exception{d.getHitbox().clicked=true;d.update();check(d.isOpen,"native dropdown opened");Object r=d.rows.get(row);Hitbox h=(Hitbox)StateMod.field(r,"hb");clicked(h);d.update();}
    void capture(String name){shot=HistoryScreen.zh()?name:name.replace("-zh","-en");captured=false;}
    public void receivePostRender(SpriteBatch sb){if(shot==null||captured)return;try{sb.flush();Pixmap pixmap=ScreenUtils.getFrameBufferPixmap(0,0,Gdx.graphics.getWidth(),Gdx.graphics.getHeight());PixmapIO.PNG png=new PixmapIO.PNG();png.setFlipY(true);png.write(new FileHandle(shot+".png"),pixmap);png.dispose();pixmap.dispose();captured=true;shot=null;}catch(Throwable e){finish(e);}}
    void finish(Throwable error){try{report.addProperty("status",error==null?"pass":"fail");report.addProperty("dataset_origin","real_player_records_read_only");report.addProperty("test_environment",true);report.addProperty("input","synthetic native hitbox/button controls; not a human demonstration");report.addProperty("stage",stage);report.addProperty("error",error==null?"":error.toString());Files.write(Paths.get("ui-options-result.json"),report.toString().getBytes(StandardCharsets.UTF_8));}catch(Exception ignored){}if(error!=null)error.printStackTrace();Gdx.app.exit();}
    static String valueOf(StatsScreen s,String key){String label=s.label(key);for(StatsScreen.Cell c:s.metricRows.values())if(c.label.equals(label))return c.value;return null;}
    static String joined(List<String> lines){StringBuilder b=new StringBuilder();for(String l:lines)b.append(l).append('\n');return b.toString();}
    static int[] pngSize(Path file)throws Exception{byte[] b=Files.readAllBytes(file);check(b.length>24&&(b[0]&255)==137&&(b[1]&255)=='P',"PNG header "+file);int w=((b[16]&255)<<24)|((b[17]&255)<<16)|((b[18]&255)<<8)|(b[19]&255),h=((b[20]&255)<<24)|((b[21]&255)<<16)|((b[22]&255)<<8)|(b[23]&255);return new int[]{w,h};}
    static Set<String> fileNames(Path dir)throws Exception{Set<String> out=new TreeSet<String>();try(DirectoryStream<Path> s=Files.newDirectoryStream(dir)){for(Path p:s)out.add(p.getFileName().toString());}return out;}
    static JsonObject metadata(Path dir)throws Exception{return new JsonParser().parse(new String(Files.readAllBytes(dir.resolve("metadata.json")),StandardCharsets.UTF_8)).getAsJsonObject();}
    static void longImage(Path dir,String name,String kind)throws Exception{
        int[] size=pngSize(dir.resolve(name));check(size[0]==1600&&size[1]>365,"long image "+name+" is "+size[0]+"x"+size[1]);
        JsonObject meta=metadata(dir);check(meta.get("kind").getAsString().equals(kind),"metadata kind "+kind);check(meta.getAsJsonArray("views").size()>=1,"at least one view written for "+kind);
    }

    public void receivePostUpdate(){if(System.currentTimeMillis()<next)return;next=System.currentTimeMillis()+700;try{
      if(System.currentTimeMillis()-started>180000)throw new AssertionError("stats options UI timeout stage "+stage);
      HistoryScreen h=HistoryScreen.instance;
      switch(stage){
       case 0:if(CardCrawlGame.mainMenuScreen==null||CardCrawlGame.mode!=CardCrawlGame.GameMode.CHAR_SELECT||CardCrawlGame.mainMenuScreen.screen!=MainMenuScreen.CurScreen.MAIN_MENU||((com.badlogic.gdx.graphics.Color)fade()).a>.01f)return;prior=CardCrawlGame.mainMenuScreen.screen;MenuButton entry=null;for(MenuButton b:CardCrawlGame.mainMenuScreen.buttons)if(b.result==HistoryHooks.STATE_NOTES)entry=b;check(entry!=null,"real native entry");clicked(entry.hb);CardCrawlGame.mainMenuScreen.update();check(HistoryScreen.active(),"native entry opens ledger");clicked(HistoryScreen.instance.home);HistoryScreen.instance.update();stage++;break;
       case 1:if(h.indexTask!=null||h.stats.task!=null||!h.stats.requested)return;check(!h.historyMode,"statistics reachable in one click");if(!h.stats.advanced){clicked(h.stats.advancedButton);h.update();}check(h.stats.index.nativeFiles>=50,"more than fifty native .run files read: "+h.stats.index.nativeFiles);check(h.stats.index.errors.isEmpty(),"no native read errors: "+h.stats.index.errors);check(h.stats.selection.runs.size()>=30,"selected slot-0 runs: "+h.stats.selection.runs.size());capture("stats-options-overview-zh");stage++;break;
       case 2:if(!captured)return;clicked(h.stats.themes[2]);h.update();check(!h.stats.campfireShown(),"campfire rate menu is hidden before the campfire page");dropdown(h.stats.category,4);check(h.stats.campfireShown(),"campfire page shows its rate menu");check(h.stats.visibleMenus().contains(h.stats.campfireMenu),"campfire menu is a visible control");String visits=valueOf(h.stats,"campfire_visits:1");check(visits!=null&&visits.contains("次"),"the rest-site total is a count: "+visits);String card=null;for(String k:h.stats.metrics.keySet())if(k.startsWith("campfire_count:1:")&&!k.endsWith(":REST")&&!k.endsWith(":SMITH")&&!k.endsWith(":RECALL")&&!k.endsWith(":PURGE")&&!k.endsWith(":LIFT")&&!k.endsWith(":DIG")){card=k;break;}check(card!=null,"smiths are counted one card at a time: "+h.stats.metrics.keySet());String count=valueOf(h.stats,card);check(count!=null&&count.contains("次"),"card count shows a number: "+count);check(joined(h.stats.display).contains("行动次数"),"action-count note");report.addProperty("campfire_count_rows",h.stats.metrics.size());capture("stats-options-campfire-counts-zh");stage++;break;
       case 3:if(!captured)return;dropdown(h.stats.campfireMenu,1);check(h.stats.campfireMode==1,"campfire menu switches to the standardized multiple view");String pref=null;for(String k:h.stats.metrics.keySet())if(k.startsWith("campfire_pref:1:")&&!k.endsWith(":RECALL")&&!k.endsWith(":PURGE")&&!k.endsWith(":LIFT")&&!k.endsWith(":DIG")){pref=k;break;}check(pref!=null,"per-card preference rows exist");String value=valueOf(h.stats,pref);check(value!=null&&value.contains("%")&&value.contains("×")&&value.contains("/"),"card row shows share, multiple and chosen/visits: "+value);String sleep=valueOf(h.stats,"campfire_sleep:1");check(sleep!=null&&sleep.contains("%")&&!sleep.contains("×"),"sleep stays a plain share: "+sleep);check(joined(h.stats.display).contains("标准化倍"),"standardized-multiple note");check(joined(h.stats.display).contains("随机基线"),"the shared random baseline is printed");int rows=0;for(StatsScreen.Line row:h.stats.displayRows)if(row.lValue!=null&&row.lValue.contains("×"))rows++;check(rows>=2,"several preference rows listed: "+rows);report.addProperty("campfire_preference_rows",rows);capture("stats-options-campfire-standard-zh");stage++;break;
       case 4:if(!captured)return;clicked(h.stats.themes[1]);h.update();dropdown(h.stats.category,4);check(h.stats.rateShown()&&!h.stats.campfireShown(),"Neow page shows the rate menu only");check(h.stats.visibleMenus().contains(h.stats.rateMenu)&&!h.stats.visibleMenus().contains(h.stats.campfireMenu),"only the rate menu is visible");check(!h.stats.neowShares.isEmpty(),"Neow shares are fitted from the skipped log");check(h.stats.neowShares.size()>=2,"at least two Neow options share the screen");double total=0;for(double v:h.stats.neowShares.values())total+=v;check(Math.abs(total-100)<1e-6,"Neow shares sum to 100: "+total);String observed=valueOf(h.stats,"neow:HUNDRED_GOLD / NONE");check(observed!=null&&observed.contains("/"),"observed Neow row keeps picked / offered: "+observed);neowObserved=observed;capture("stats-options-neow-observed-zh");stage++;break;
       case 5:if(!captured)return;dropdown(h.stats.rateMenu,1);check(h.stats.rateMode==1,"rate menu switches to standardized");String standard=valueOf(h.stats,"neow:HUNDRED_GOLD / NONE");Double fit=h.stats.standardShare("neow:HUNDRED_GOLD / NONE");check(fit!=null&&standard!=null&&standard.equals(String.format(Locale.ROOT,"%.2f%%",fit.doubleValue())),"Neow row shows its fitted share: "+standard);check(!standard.equals(neowObserved),"the standardized view replaces the observed row: "+standard);check(joined(h.stats.display).contains("涅奥标准率"),"Neow standardized note");capture("stats-options-neow-standard-zh");stage++;break;
       case 6:if(!captured)return;dropdown(h.stats.category,5);check(h.stats.bossShares.size()>=1,"boss relics are fitted per act");double bossTotal=0;for(double v:h.stats.bossShares.get(1).values())bossTotal+=v;check(Math.abs(bossTotal-100)<1e-6,"act-1 boss shares sum to 100: "+bossTotal);String skip=valueOf(h.stats,"boss:1:SKIP");check("—".equals(skip),"Skip stays an opponent outside the shares: "+skip);String relic=null;Double relicFit=null;for(Map.Entry<String,Double> e:h.stats.bossShares.get(1).entrySet()){relic=e.getKey();relicFit=e.getValue();break;}String relicValue=valueOf(h.stats,"boss:1:"+relic);check(relicValue!=null&&relicValue.equals(String.format(Locale.ROOT,"%.2f%%",relicFit.doubleValue())),"boss relic row shows its fitted share: "+relicValue);report.addProperty("boss_share_act1",relic+" "+relicValue);check(joined(h.stats.display).contains("Boss 遗物标准率"),"boss standardized note");capture("stats-options-boss-standard-zh");stage++;break;
       case 7:if(!captured)return;clicked(h.stats.themes[2]);h.update();dropdown(h.stats.category,3);check(!h.stats.campfireShown()&&!h.stats.visibleMenus().contains(h.stats.campfireMenu),"shops page hides the campfire menu");clicked(h.stats.themes[0]);h.update();check(!h.stats.rateShown()&&!h.stats.visibleMenus().contains(h.stats.rateMenu),"overview hides the rate menu");
        String win=valueOf(h.stats,"win");check(win!=null&&win.contains("95%区间")&&win.contains("%"),"win rate carries a 95% interval: "+win);StringBuilder intervals=new StringBuilder();for(String k:Arrays.asList("deck_size","score","purge_shop","purge_event","purge_total")){String v=valueOf(h.stats,k);check(v!=null&&v.contains("95%区间"),k+" carries a mean interval: "+v);intervals.append(k).append('=').append(v).append("; ");}check(joined(h.stats.display).contains("TinyCat"),"removal definition is stated");report.addProperty("overview_intervals",intervals.toString());
        report.addProperty("campfire_share_multiple_switch",true);report.addProperty("neow_standardized",true);report.addProperty("boss_standardized",true);capture("stats-options-overview-ci-zh");stage=8;break;
       case 8:if(!captured)return;clicked(h.stats.themes[3]);h.update();check(h.stats.theme==3,"charts tab opens");check(h.stats.visibleMenus().contains(h.stats.chartKind),"content menu is a visible control");check(h.stats.chart.kind==0&&h.stats.visibleMenus().contains(h.stats.chartAct),"cards show the act menu");if(h.stats.rateMode!=0)dropdown(h.stats.rateMenu,0);check(h.stats.chart.mode==0,"cards start on the observed view");check(!h.stats.chart.rows.isEmpty()&&!h.stats.chart.entries.isEmpty(),"cards are laid out from real screens");Metric skipMetric=h.stats.metrics.get("skip:"+h.stats.chart.act);boolean hasSkip=false;for(PickTiers.Entry e:h.stats.chart.entries)if(PickRateChart.SKIP.equals(e.card))hasSkip=true;check(skipMetric==null||hasSkip,"Skip is drawn as its own blank tile");Metric bowlMetric=h.stats.metrics.get("bowl:"+h.stats.chart.act);boolean hasBowl=false;for(PickTiers.Entry e:h.stats.chart.entries)if(PickRateChart.BOWL.equals(e.card))hasBowl=true;check(bowlMetric==null||hasBowl,"Singing Bowl is drawn with its relic image");check(h.stats.chart.exportable(),"cards are exportable");report.addProperty("chart_cards_entries",h.stats.chart.entries.size());capture("stats-options-chart-cards-zh");stage=9;break;
       case 9:if(!captured)return;exportBefore=h.stats.chart.lastExport;clicked(h.stats.exportButton);h.update();stage=10;break;
       case 10:if(h.stats.chart.lastExport==null||h.stats.chart.lastExport.equals(exportBefore))return;Path cards=h.stats.chart.lastExport;Set<String> cardFiles=fileNames(cards);check(cardFiles.contains("act-1.png")&&cardFiles.contains("act-1-standardized.png")&&cardFiles.contains("metadata.json"),"cards export writes both views: "+cardFiles);longImage(cards,"act-1.png","cards");check(h.stats.chart.message.startsWith(HistoryScreen.tr("图片已保存：","Saved: ")),"cards export reported success: "+h.stats.chart.message);JsonObject cardMeta=metadata(cards);List<String> cardViews=new ArrayList<String>();for(JsonElement e:cardMeta.getAsJsonArray("views"))cardViews.add(e.getAsString());check(cardViews.contains("observed")&&cardViews.contains("standardized"),"cards metadata lists both views: "+cardViews);check(cardMeta.getAsJsonArray("entries").size()>0&&"cards".equals(cardMeta.get("kind").getAsString()),"cards entries recorded");report.addProperty("chart_cards_files",cardFiles.toString());capture("stats-options-chart-cards-saved-zh");stage=11;break;
       case 11:if(!captured)return;dropdown(h.stats.chartKind,1);check(h.stats.chart.kind==1&&!h.stats.visibleMenus().contains(h.stats.chartAct)&&h.stats.visibleMenus().contains(h.stats.chartCampfireRate),"campfire hides the act menu and shows its own rate menu");check(!h.stats.chart.sections.isEmpty()&&!h.stats.chart.listLines.isEmpty(),"campfire sections are laid out from real choices");check(h.stats.chart.exportable(),"campfire is exportable");capture("stats-options-chart-campfire-zh");stage=12;break;
       case 12:if(!captured)return;exportBefore=h.stats.chart.lastExport;clicked(h.stats.exportButton);h.update();stage=13;break;
       case 13:if(h.stats.chart.lastExport==null||h.stats.chart.lastExport.equals(exportBefore))return;Path campfire=h.stats.chart.lastExport;Set<String> campFiles=fileNames(campfire);check(campFiles.contains("campfire.png")&&campFiles.contains("campfire-standardized.png")&&campFiles.contains("metadata.json"),"campfire export writes both views: "+campFiles);longImage(campfire,"campfire.png","campfire");check(h.stats.chart.message.startsWith(HistoryScreen.tr("图片已保存：","Saved: ")),"campfire export reported success: "+h.stats.chart.message);JsonObject campMeta=metadata(campfire);check(campMeta.getAsJsonArray("observed_sections").size()>0&&campMeta.getAsJsonArray("standardized_sections").size()>0,"campfire sections recorded for both views");report.addProperty("chart_campfire_files",campFiles.toString());capture("stats-options-chart-campfire-saved-zh");stage=14;break;
       case 14:if(!captured)return;dropdown(h.stats.chartKind,2);check(h.stats.chart.kind==2&&h.stats.visibleMenus().contains(h.stats.rateMenu),"Neow shows the shared rate menu");check(!h.stats.chart.sections.isEmpty(),"Neow sections are laid out from the skipped log");check(!h.stats.neowShares.isEmpty(),"Neow standardized shares are available");capture("stats-options-chart-neow-zh");stage=15;break;
       case 15:if(!captured)return;exportBefore=h.stats.chart.lastExport;clicked(h.stats.exportButton);h.update();stage=16;break;
       case 16:if(h.stats.chart.lastExport==null||h.stats.chart.lastExport.equals(exportBefore))return;Path neow=h.stats.chart.lastExport;Set<String> neowFiles=fileNames(neow);check(neowFiles.contains("neow.png")&&neowFiles.contains("neow-standardized.png")&&neowFiles.contains("metadata.json"),"Neow export writes both views: "+neowFiles);longImage(neow,"neow.png","neow");check(h.stats.chart.message.startsWith(HistoryScreen.tr("图片已保存：","Saved: ")),"neow export reported success: "+h.stats.chart.message);JsonObject neowMeta=metadata(neow);check(neowMeta.getAsJsonArray("observed_sections").size()>0&&neowMeta.getAsJsonArray("standardized_sections").size()>0,"Neow sections recorded for both views");report.addProperty("chart_neow_files",neowFiles.toString());capture("stats-options-chart-neow-saved-zh");stage=17;break;
       case 17:if(!captured)return;dropdown(h.stats.chartKind,3);check(h.stats.chart.kind==3&&!h.stats.visibleMenus().contains(h.stats.chartAct)&&h.stats.visibleMenus().contains(h.stats.rateMenu),"Boss relics hide the act menu and keep the rate menu");check(!h.stats.chart.sections.isEmpty(),"Boss relic sections are laid out per act");check(!h.stats.bossShares.isEmpty(),"Boss standardized shares are available");capture("stats-options-chart-boss-zh");stage=18;break;
       case 18:if(!captured)return;exportBefore=h.stats.chart.lastExport;clicked(h.stats.exportButton);h.update();stage=19;break;
       case 19:if(h.stats.chart.lastExport==null||h.stats.chart.lastExport.equals(exportBefore))return;Path boss=h.stats.chart.lastExport;Set<String> bossFiles=fileNames(boss);check(bossFiles.contains("boss.png")&&bossFiles.contains("boss-standardized.png")&&bossFiles.contains("metadata.json"),"Boss export writes both views: "+bossFiles);longImage(boss,"boss.png","boss");check(h.stats.chart.message.startsWith(HistoryScreen.tr("图片已保存：","Saved: ")),"boss export reported success: "+h.stats.chart.message);JsonObject bossMeta=metadata(boss);check(bossMeta.getAsJsonArray("observed_sections").size()>0&&bossMeta.getAsJsonArray("standardized_sections").size()>0,"Boss sections recorded for both views");report.addProperty("chart_boss_files",bossFiles.toString());report.addProperty("chart_long_images_exported",true);capture("stats-options-chart-boss-saved-zh");stage=20;break;
       case 20:if(!captured)return;finish(null);stage=99;break;
      }
    }catch(Throwable e){finish(e);stage=99;}}
}
